mapper.update:
UPDATE dining_table
table_no = #{tableNo}, area = #{area}, capacity = #{capacity}, status = #{status}, pos_x = #{posX}, pos_y = #{posY}, shape = #{shape},
WHERE id = #{id}

mapper.select:
SELECT * FROM dining_table
WHERE capacity >= #{peopleCount}
AND id NOT IN (
SELECT table_id FROM reservation
WHERE reserve_date = #{reserveDate}
AND status IN ('待确认', '已确认', '已到店')
AND table_id IS NOT NULL
AND (
(reserve_time >= #{startTime} AND reserve_time <= #{endTime})
)
)
ORDER BY capacity ASC, table_no ASC
